const items = $input.all();
if (items.length !== 1 || !items[0].binary?.file) {
  throw new Error("Expected exactly one multipart spreadsheet in field 'file'.");
}
const file = items[0].binary.file;
if (!file.fileName || !/\.(csv|xlsx)$/i.test(file.fileName)) {
  throw new Error("The uploaded file must have a .csv or .xlsx filename.");
}
return items;

const batch = $input.first().json;
const required = [
  'id', 'source_name', 'status', 'total_rows', 'processed_rows', 'failed_rows',
  'straight_through_approved', 'ever_required_human_review',
  'currently_review_required', 'ready_for_approval'
];
const missing = required.filter((field) => batch[field] === undefined || batch[field] === null);
if (missing.length) {
  throw new Error(`FastAPI returned an invalid batch payload; missing: ${missing.join(', ')}`);
}
return $input.all();

const batch = $('Validate batch response').first().json;
const products = $input.all()
  .flatMap((item) => Array.isArray(item.json) ? item.json : [item.json])
  .filter((product) => product && product.id);
const attentionStatuses = new Set(['review_required', 'ready_for_approval']);
const productsNeedingAttention = products
  .filter((product) => attentionStatuses.has(product.status))
  .map((product) => ({
    id: product.id,
    status: product.status,
    source_row_number: product.source_row_number,
    product_name: product.product?.product_name ?? null,
    issue_codes: (product.issues ?? []).map((issue) => issue.code),
  }));
const failedRows = Number(batch.failed_rows);
const everReviewed = Number(batch.ever_required_human_review);
const currentlyReview = Number(batch.currently_review_required);
const ready = Number(batch.ready_for_approval);
const clean = failedRows === 0 && everReviewed === 0;
const humanReview = everReviewed > 0 || currentlyReview > 0 || ready > 0;
const partialErrors = failedRows > 0;
const messages = [];
if (clean) messages.push('Batch processed automatically; no human review required.');
if (humanReview) messages.push('Batch contains products that require or required human review.');
if (partialErrors) messages.push('Batch completed with row-level ingestion failures.');
return [{
  json: {
    batch_id: batch.id,
    filename: batch.source_name,
    batch_status: batch.status,
    total_rows: batch.total_rows,
    processed_rows: batch.processed_rows,
    failed_rows: batch.failed_rows,
    status_counts: {
      straight_through_approved: batch.straight_through_approved,
      ever_required_human_review: batch.ever_required_human_review,
      currently_review_required: batch.currently_review_required,
      ready_for_approval: batch.ready_for_approval,
      human_approved: batch.human_approved,
      rejected: batch.rejected,
    },
    outcomes: {
      clean_straight_through: clean,
      human_review: humanReview,
      partial_ingestion_errors: partialErrors,
    },
    messages,
    products_needing_attention: productsNeedingAttention,
    row_errors: batch.row_errors ?? [],
    review_ui_url: 'http://localhost:8501',
  },
}];
